const row = $input.first().json || {};
const body = row.body && typeof row.body === 'object' ? row.body : row;
function normalizeShotToken(v) {
  const raw = String(v || '').trim();
  if (!raw) return '';
  if (/^shot[_-]?\d+$/i.test(raw)) {
    const num = raw.match(/(\d+)/)?.[1] || '';
    return num ? 'shot_' + num : raw;
  }
  if (/^\d+$/.test(raw)) return 'shot_' + raw;
  return raw;
}
function truthyFlag(v) {
  if (v === true) return true;
  return ['1', 'true', 'yes', 'on'].includes(String(v || '').trim().toLowerCase());
}
function normalizeConcurrency(v) {
  const n = Number(v);
  if (!Number.isFinite(n)) return 3;
  return Math.max(1, Math.min(4, Math.floor(n)));
}
const normalizedBadShotIds = String(body.bad_shot_ids ?? body['需重做镜头编号'] ?? '')
  .split(/[\n,，\s]+/)
  .map(normalizeShotToken)
  .filter(Boolean);
return [{
  json: {
    ...body,
    review_decision: body.review_decision ?? body['确认结论'] ?? body.decision ?? '',
    bad_shot_ids: normalizedBadShotIds.join(','),
    bad_shot_ids_list: normalizedBadShotIds,
    review_feedback: body.review_feedback ?? body['修改意见'] ?? '',
    review_round_hidden: body.review_round_hidden ?? body.review_round ?? 1,
    review_context_path_hidden: body.review_context_path_hidden ?? body.review_context_path ?? '',
    project_id: body.project_id || '',
    product_name: body.product_name || '',
    rerun_failed_only: truthyFlag(body.rerun_failed_only),
    rerun_pending_only: truthyFlag(body.rerun_pending_only),
    video_concurrency: normalizeConcurrency(body.video_concurrency ?? body.video_generation_concurrency ?? 3),
  },
}];

const process = require('process');
const PROJECT_ROOT = process.env.TIKTOK_WORKFLOW_ROOT || process.env.PROJECT_ROOT || process.cwd();
const DATA_ROOT = require('process').env.WORKFLOW_DATA_ROOT || (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'workflow-data') : require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data')) || require('process').env.AI_VIDEO_RUNTIME_ROOT || PROJECT_ROOT;
const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};

function normalizeDecision(v) {
  const s = String(v || '').trim().toLowerCase();
  if (!s) return true;
  if (s.includes('重做') || s.includes('redo') || s.includes('reject') || s.includes('revise')) return false;
  if (s.includes('通过') || s.includes('approve') || s.includes('pass') || s === 'ok' || s === 'yes' || s === 'y') return true;
  return true;
}

function normalizeShotToken(v) {
  const raw = String(v || '').trim();
  if (!raw) return '';
  if (/^shot[_-]?\d+$/i.test(raw)) {
    const num = raw.match(/(\d+)/)?.[1] || '';
    return num ? 'shot_' + num : raw;
  }
  if (/^\d+$/.test(raw)) return 'shot_' + raw;
  return raw;
}
function normalizeReviewContextPath(contextPath) {
  let normalized = String(contextPath || '').trim();
  while (normalized.endsWith('.submitted.json')) {
    normalized = normalized.slice(0, -'.submitted.json'.length);
  }
  return normalized;
}


const rerunFailedOnly = !!row.rerun_failed_only;
const rerunPendingOnly = !!row.rerun_pending_only;
const decisionValue = row.review_decision ?? row['确认结论'] ?? row.decision ?? '';
const approved = rerunFailedOnly ? true : normalizeDecision(decisionValue);
const badShotIds = String(row.bad_shot_ids ?? row['需重做镜头编号'] ?? '')
  .split(/[\n,，\s]+/)
  .map(normalizeShotToken)
  .filter(Boolean);
const feedback = String(row.review_feedback ?? row['修改意见'] ?? '').trim();
function normalizeConcurrency(v) { const n = Number(v); return Number.isFinite(n) ? Math.max(1, Math.min(4, Math.floor(n))) : 3; }
const videoConcurrency = normalizeConcurrency(row.video_concurrency ?? row.video_generation_concurrency ?? 3);
const currentRound = Number(row.review_round || row['review_round_hidden'] || 1);
const reviewContextPath = normalizeReviewContextPath(row.review_context_path || row['review_context_path_hidden'] || '');
let reviewContext = {};

if (reviewContextPath) {
  if (!fs.existsSync(reviewContextPath)) {
    throw new Error('解析用户确认：确认上下文文件不存在 ' + reviewContextPath);
  }
  try {
    reviewContext = JSON.parse(fs.readFileSync(reviewContextPath, 'utf8'));
  } catch (e) {
    throw new Error('解析用户确认：确认上下文文件不是合法 JSON，详情：' + e.message);
  }
}

let panels = Array.isArray(reviewContext.panel_review_pack) ? reviewContext.panel_review_pack : [];
const projectId = row.project_id || reviewContext.project_id || '';
const progressPath = projectId
  ? path.join(DATA_ROOT, '.n8n-local-cache', 'review-progress', 'review_progress_' + String(projectId).replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json')
  : '';
let progress = {};
if (progressPath && fs.existsSync(progressPath)) {
  try {
    progress = JSON.parse(fs.readFileSync(progressPath, 'utf8'));
  } catch (e) {}
}

if (rerunFailedOnly) {
  if (badShotIds.length > 0) {
    // Explicit single-shot rerun: select by bad_shot_ids regardless of progress status
    const explicitIdSet = new Set(badShotIds.flatMap(function(s){var n=String(s);return [n, n.replace(/^shot_/,'')];}));
    const explicitOrderSet = new Set(badShotIds.map((s) => String(s).replace(/^shot_/, '')));
    const shotStateMap = new Map(
      (Array.isArray(progress.shots) ? progress.shots : []).map((shot) => [String(shot.shot_id), shot])
    );
    panels = panels
      .filter((panel) => explicitIdSet.has(String(panel.shot_id)) || explicitOrderSet.has(String(panel.shot_order)))
      .map((panel) => {
        const shotState = shotStateMap.get(String(panel.shot_id)) || {};
        return {
          ...panel,
          veo_fail_streak: Number(shotState.veo_fail_streak || panel.veo_fail_streak || 0),
          veo_prompt_regen_count: Number(shotState.veo_prompt_regen_count || panel.veo_prompt_regen_count || 0),
          veo_generation_attempt_total: Number(shotState.veo_generation_attempt_total || panel.veo_generation_attempt_total || 0),
          veo_failure_history: Array.isArray(shotState.veo_failure_history) ? shotState.veo_failure_history : (Array.isArray(panel.veo_failure_history) ? panel.veo_failure_history : []),
        };
      });
    if (!panels.length) {
      throw new Error('只重跑指定镜头：bad_shot_ids 未能在 review_context 中匹配到对应 panel');
    }
  } else {
    // Bulk failed rerun (no explicit shot IDs): unchanged behavior
    const failedShots = Array.isArray(progress.shots)
      ? progress.shots.filter((shot) => String(shot.status || '') === 'failed')
      : [];
    if (!failedShots.length) {
      throw new Error('只重跑失败镜头：当前没有可重跑的失败镜头');
    }
    const failedIdSet = new Set(failedShots.map((shot) => String(shot.shot_id)));
    const failedOrderSet = new Set(failedShots.map((shot) => String(shot.shot_order)));
    const shotStateMap = new Map(failedShots.map((shot) => [String(shot.shot_id), shot]));
    panels = panels
      .filter((panel) => failedIdSet.has(String(panel.shot_id)) || failedOrderSet.has(String(panel.shot_order)))
      .map((panel) => {
        const shotState = shotStateMap.get(String(panel.shot_id)) || {};
        return {
          ...panel,
          veo_fail_streak: Number(shotState.veo_fail_streak || panel.veo_fail_streak || 0),
          veo_prompt_regen_count: Number(shotState.veo_prompt_regen_count || panel.veo_prompt_regen_count || 0),
          veo_generation_attempt_total: Number(shotState.veo_generation_attempt_total || panel.veo_generation_attempt_total || 0),
          veo_failure_history: Array.isArray(shotState.veo_failure_history) ? shotState.veo_failure_history : (Array.isArray(panel.veo_failure_history) ? panel.veo_failure_history : []),
        };
      });
    if (!panels.length) {
      throw new Error('只重跑失败镜头：失败镜头未能在 review_context 中匹配到对应 panel');
    }
  }
}

if (rerunPendingOnly) {
  const pendingShots = Array.isArray(progress.shots)
    ? progress.shots.filter((shot) => String(shot.status || 'pending') === 'pending')
    : [];
  if (!pendingShots.length) {
    throw new Error('继续生成剩余镜头：当前没有待生成镜头');
  }
  const pendingIdSet = new Set(pendingShots.map((shot) => String(shot.shot_id)));
  const pendingOrderSet = new Set(pendingShots.map((shot) => String(shot.shot_order)));
  const shotStateMap = new Map(pendingShots.map((shot) => [String(shot.shot_id), shot]));
  panels = panels
    .filter((panel) => pendingIdSet.has(String(panel.shot_id)) || pendingOrderSet.has(String(panel.shot_order)))
    .map((panel) => {
      const shotState = shotStateMap.get(String(panel.shot_id)) || {};
      return {
        ...panel,
        veo_fail_streak: Number(shotState.veo_fail_streak || panel.veo_fail_streak || 0),
        veo_prompt_regen_count: Number(shotState.veo_prompt_regen_count || panel.veo_prompt_regen_count || 0),
        veo_generation_attempt_total: Number(shotState.veo_generation_attempt_total || panel.veo_generation_attempt_total || 0),
        veo_failure_history: Array.isArray(shotState.veo_failure_history) ? shotState.veo_failure_history : (Array.isArray(panel.veo_failure_history) ? panel.veo_failure_history : []),
      };
    });
  if (!panels.length) {
    throw new Error('继续生成剩余镜头：待生成镜头未能在 review_context 中匹配到对应 panel');
  }
}

return [{
  json: {
    ...reviewContext,
    ...row,
    project_id: projectId,
    product_name: row.product_name || reviewContext.product_name || '',
    panel_review_pack: panels,
    review_context_path: reviewContextPath || normalizeReviewContextPath(reviewContext.review_context_path || '') || '',
    review_approved: approved,
    review_feedback: feedback,
    bad_shot_ids: badShotIds.join(','),
    bad_shot_ids_list: badShotIds,
    review_round: approved ? currentRound : currentRound + 1,
    previous_review_round: currentRound,
    manual_regeneration_requested: !approved,
    rerun_failed_only: rerunFailedOnly,
    rerun_pending_only: rerunPendingOnly,
    review_progress_path: progressPath,
    video_concurrency: videoConcurrency,
  },
}];

const fs = require('fs');

const row = $input.first().json || {};

function normalizeReviewContextPath(contextPath) {
  let normalized = String(contextPath || '').trim();
  while (normalized.endsWith('.submitted.json')) {
    normalized = normalized.slice(0, -'.submitted.json'.length);
  }
  return normalized;
}

let panels = Array.isArray(row.panel_review_pack) ? row.panel_review_pack : [];
const reviewContextPath = normalizeReviewContextPath(row.review_context_path || row.review_context_path_hidden || '');

if (!panels.length && reviewContextPath && fs.existsSync(reviewContextPath)) {
  try {
    const ctx = JSON.parse(fs.readFileSync(reviewContextPath, 'utf8'));
    if (Array.isArray(ctx.panel_review_pack)) {
      panels = ctx.panel_review_pack;
    }
  } catch (e) {
    throw new Error('恢复已确认分镜：无法读取确认上下文，详情：' + e.message);
  }
}

if (!panels.length) {
  throw new Error('恢复已确认分镜：panel_review_pack 为空');
}


// D-fix: filter shots by status to prevent duplicate Veo submissions
const _rerunPendingOnly = Boolean(row.rerun_pending_only);
const _rerunFailedOnly = Boolean(row.rerun_failed_only);
const _badShotIds = String(row.bad_shot_ids || '').split(',').map(s => s.trim()).filter(Boolean);
const _progressPath = String(row.review_progress_path || '').trim();
const _existingStatuses = {};
if (_progressPath && fs.existsSync(_progressPath)) {
  try {
    const _prog = JSON.parse(fs.readFileSync(_progressPath, 'utf8'));
    for (const _shot of (Array.isArray(_prog.shots) ? _prog.shots : [])) {
      _existingStatuses[String(_shot.shot_id || '')] = String(_shot.status || 'pending').toLowerCase();
    }
  } catch (_e) {}
}
const SKIP_STATUSES = ['completed', 'done', 'submitted', 'running'];


// D-fix: apply shot filter before processing
const _panelsFiltered = _rerunPendingOnly || _rerunFailedOnly
  ? panels.filter(panel => {
      const shotId = String(panel.shot_id || '');
      const status = _existingStatuses[shotId] || _existingStatuses['shot_' + shotId] || 'pending';
      if (_rerunFailedOnly) {
        if (_badShotIds.length > 0) return _badShotIds.includes(shotId) || _badShotIds.includes('shot_' + shotId);
        return status === 'failed';
      }
      return status === 'pending' || !status;
    })
  : panels;

// B8AJ0 (TEST-ONLY): cap the per-shot video list when the smoke wrote a max-shots marker.
// Production NEVER writes this file -> no cap -> all confirmed shots run unchanged. The JS
// Task Runner only inherits HOME, so resolve %APPDATA%/HOME like the rest of WF03 (B8AD).
let _smokeShotCap = 0;
try {
  const _p = require('path'); const _os = require('os'); const _pe = require('process');
  const _dataRoot = _pe.env.WORKFLOW_DATA_ROOT || (_pe.platform === 'win32'
    ? _p.join(_pe.env.APPDATA || _p.join(_pe.env.USERPROFILE || _pe.env.HOME || _os.homedir(), 'AppData', 'Roaming'), 'AI Video', 'workflow-data')
    : _p.join(_os.homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data'));
  const _capPath = _p.join(_dataRoot, '.n8n-local-cache', '.smoke-max-shots');
  if (fs.existsSync(_capPath)) {
    const _n = parseInt(String(fs.readFileSync(_capPath, 'utf8')).trim(), 10);
    if (Number.isInteger(_n) && _n > 0) _smokeShotCap = _n;
  }
} catch (_e) { _smokeShotCap = 0; }
