function runProcess(cmd,args,label){return new Promise((resolve,reject)=>{const out=[];const err=[];const child=spawn(cmd,args,{stdio:['ignore','pipe','pipe']});child.stdout.on('data',c=>out.push(c));child.stderr.on('data',c=>err.push(c));child.on('error',reject);child.on('close',code=>{if(code!==0){reject(new Error((label||cmd)+' 失败：'+Buffer.concat(err).toString('utf8').slice(0,1000)));return;}resolve(Buffer.concat(out));});});}

function getProxy() {
  try {
    const candidates = [
      require('process').env.AI_VIDEO_CONFIG_PATH,
      (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'config', 'local-config.json') : (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'config', 'local-config.json') : require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'config', 'local-config.json'))),
    ].filter(Boolean);
    for (const cfgPath of candidates) {
      const cfg = fs.existsSync(cfgPath) ? JSON.parse(fs.readFileSync(cfgPath, 'utf8')) : {};
      if (cfg.https_proxy) return cfg.https_proxy;
    }
  } catch (e) {}
  const env = (typeof process !== 'undefined' ? process.env : {}) || {};
  return env.HTTPS_PROXY || env.https_proxy || env.ALL_PROXY || env.all_proxy || '';
}

async function resolveHostWithPublicDns(hostname) {
  const servers = ['1.1.1.1', '8.8.8.8'];
  for (const server of servers) {
    try {
      const stdout = (await runProcess('dig', ['@' + server, '+short', hostname], 'DNS 查询')).toString('utf8');
      const ip = stdout.split(/\r?\n/).map(l => l.trim()).find(l => /^\d+\.\d+\.\d+\.\d+$/.test(l) && !l.startsWith('127.'));
      if (ip) return ip;
    } catch (e) {}
  }
  return '';
}

async function saveRemoteFile(url, targetPath) {
  const parsed = new URL(url);
  const host = parsed.hostname;
  const proxy = getProxy();
  const proxyArgs = proxy ? ['--proxy', proxy] : [];
  const baseArgs = ['-L', '-sS', '--connect-timeout', '12', '--max-time', '120', '--retry', '1', '--retry-delay', '2', ...proxyArgs];
  const attempts = [];
  if (!proxy) {
    const publicIp = await resolveHostWithPublicDns(host);
    if (publicIp) {
      attempts.push([...baseArgs, '--resolve', host + ':443:' + publicIp, url, '-o', targetPath]);
    }
  }
  attempts.push([...baseArgs, url, '-o', targetPath]);
  let lastError = null;
  for (const args of attempts) {
    try {
      await runProcess('curl', args, '视频下载');
      if (fs.existsSync(targetPath) && fs.statSync(targetPath).size > 0) return;
      lastError = new Error('curl 下载完成但文件为空');
    } catch (e) {
      lastError = e;
    }
  }
  throw new Error('视频下载失败：' + String(lastError?.stderr || lastError?.message || lastError || '').slice(0, 1000));
}

