const finalSourceSignature = completedShots.map((shot) => String(shot.video_path || '')).filter(Boolean).join('|');
// P13-B1: resolve bundled ffmpeg (absolute path injected by launcher); never rely on bare PATH ffmpeg silently.
const ffmpegPath = String(process.env.AI_VIDEO_FFMPEG_PATH || 'ffmpeg');
let ffmpegExists = ffmpegPath.includes('/') ? fs.existsSync(ffmpegPath) : true;
let ffmpegExecutable = false;
let ffmpegVersion = '';
try {
  const { execFileSync } = require('child_process');
  const vout = execFileSync(ffmpegPath, ['-version'], { stdio: ['ignore', 'pipe', 'ignore'], timeout: 15000 }).toString('utf8');
  ffmpegVersion = (vout.split('\n')[0] || '').trim();
  ffmpegExecutable = true;
} catch (e) {
  ffmpegExecutable = false;
}
let finalMergeFailed = false;
let finalMergeError = '';
let finalMergeCommandSummary = '';

if (status === 'success' && completedShots.length === totalPanels && totalPanels > 0) {
  // E-fix: skip ffmpeg only when the canonical final matches the current shot video set.
  // A stale final from an invalidated/rerun shot must not be reused.
  const existingFinalSourceSignature = String(progress.final_source_signature || '').trim();
  const canReuseCanonicalFinal = Boolean(
    finalMergedVideoPath &&
    fs.existsSync(finalMergedVideoPath) &&
    fs.statSync(finalMergedVideoPath).size > 0 &&
    existingFinalSourceSignature &&
    existingFinalSourceSignature === finalSourceSignature
  );
  if (canReuseCanonicalFinal) {
    finalMergedVideoName = path.basename(finalMergedVideoPath);
  } else {
    const listPath = path.join(concatDir, 'concat_' + projectId + '.txt');
    const mergedName = 'final_' + projectId + '_' + Date.now() + '.mp4';
    const mergedPath = path.join(concatDir, mergedName);
    const ffArgs = ['-y', '-f', 'concat', '-safe', '0', '-i', listPath, '-c', 'copy', '-movflags', '+faststart', mergedPath];
    finalMergeCommandSummary = [ffmpegPath].concat(ffArgs).join(' ');
    if (!ffmpegExecutable) {
      // ffmpeg unavailable: do NOT silent-fail and do NOT mark success. Clips stay
      // complete (stage video_clips_generated); surface an explicit merge failure.
      status = 'final_merge_failed';
      finalMergeFailed = true;
      finalMergeError = 'ffmpeg 不可用（路径：' + ffmpegPath + '，exists=' + ffmpegExists + '，executable=false）。最终合成未执行。';
    } else {
      try {
        const lines = completedShots.map((shot) => "file '" + String(shot.video_path || '').replace(/'/g, "'\\''") + "'");
        fs.writeFileSync(listPath, lines.join('\n') + '\n');
        await runProcess(ffmpegPath, ffArgs, 'ffmpeg 合并视频');
        if (fs.existsSync(mergedPath) && fs.statSync(mergedPath).size > 0) {
          finalMergedVideoPath = mergedPath;
          finalMergedVideoName = mergedName;
        } else {
