          finalMergeFailed = true;
          finalMergeError = 'ffmpeg 执行完成但未生成有效成片文件（输出缺失或为空）。';
        }
      } catch (error) {
        status = 'final_merge_failed';
        finalMergeFailed = true;
        finalMergeError = String((error && error.message) || error);
      }
    }
  }
}

const nextProgress = {
  ...progress,
  shots: mergedShots,
  total_panels: totalPanels,
  completed_count: completedCount,
  running_count: runningCount,
