const process = require('process');
const fs = require('fs'), path = require('path'), os = require('os');

const KIE_BASE = 'https://api.kie.ai/api';
const KIE_TEXT_MODEL_DEFAULT = 'gemini-3.1-pro';

const CONFIG_CANDIDATES = [
  process.env.AI_VIDEO_CONFIG_PATH,
  (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'config', 'local-config.json') : (require('process').platform === 'win32' ? require('path').join(require('process').env.APPDATA || require('path').join(require('process').env.USERPROFILE || require('process').env.HOME || require('os').homedir(), 'AppData', 'Roaming'), 'AI Video', 'config', 'local-config.json') : require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'config', 'local-config.json'))),
  process.env.TIKTOK_WORKFLOW_ROOT ? path.join(process.env.TIKTOK_WORKFLOW_ROOT, '版本测试', 'config', 'local-config.json') : null,
].filter(Boolean);

function loadConfigs() {
  const results = [];
  for (const p of CONFIG_CANDIDATES) {
    try { results.push({ path: p, cfg: JSON.parse(fs.readFileSync(p, 'utf8')) }); } catch(_) {}
  }
  return results;
}

function readKieConfig(taskStage) {
  for (const { cfg } of loadConfigs()) {
    const key = String(
      (cfg.providers && cfg.providers.kie && cfg.providers.kie.api_key) ||
      (cfg.kie && cfg.kie.api_key) ||
      ''
    ).trim();
    if (!key) continue;
    const taskModel = String((cfg.tasks && cfg.tasks[taskStage] && cfg.tasks[taskStage].model) || '').trim();
    const providerModel = String(
      (cfg.providers && cfg.providers.kie && cfg.providers.kie.text_model) ||
      (cfg.kie && cfg.kie.text_model) ||
      ''
    ).trim();
    const model = taskModel || providerModel || KIE_TEXT_MODEL_DEFAULT;
    const baseUrl = String(
      (cfg.providers && cfg.providers.kie && cfg.providers.kie.base_url) ||
      (cfg.kie && cfg.kie.base_url) ||
      KIE_BASE
    ).replace(/\/+$/, '');
    return { key, model, baseUrl };
  }
  const envKey = String(process.env.KIE_API_KEY || '').trim();
  if (envKey) return { key: envKey, model: KIE_TEXT_MODEL_DEFAULT, baseUrl: KIE_BASE };
  throw new Error('缺少 Kie API Key。请在「系统配置」填写 Kie API Key 并保存。');
}

function kieTextUrl(model, baseUrl) {
  const origin = baseUrl.endsWith('/api') ? baseUrl.slice(0, -4) : baseUrl.replace(/\/+$/, '');
  return origin + '/' + model + '/v1/chat/completions';
}

const { key, model, baseUrl } = readKieConfig('script_framework');
const url = kieTextUrl(model, baseUrl);
console.log('[WF03-失败修复] Kie text | model:', model);
return [{ json: { ...$json, _stage: 'script_framework', _adapter: 'kie_openai_chat', _api_key: key, _model: model, _api_url: url, _auth_header: `Bearer ${key}` } }];

// 请求体适配：根据 _adapter 将 Gemini generateContent 格式转为对应格式
const input = $json;
const adapter = input._adapter || 'gemini_native';

if (adapter === 'kie_openai_chat') {
  // Gemini format: system_instruction + contents[{role,parts}] + generationConfig
  // OpenAI format: messages[{role, content}] + model + temperature...
  const rawBody = input.request_body || {
    system_instruction: input.system_instruction,
    contents: input.contents,
    generationConfig: input.generationConfig
  };

  const sysText = (rawBody.system_instruction?.parts || []).map(p => p.text || '').join('\n').trim();
  const msgs = [];
  if (sysText) msgs.push({ role: 'system', content: sysText });

  const userParts = [];
  for (const block of (rawBody.contents || [])) {
    if ((block.role || 'user') === 'model') continue;
    for (const part of (block.parts || [])) {
      if (part.text) userParts.push({ type: 'text', text: part.text });
      // Text model calls stay text-only for Kie stability; images are reserved for the storyboard image model.
    }
  }

  const userContent = (userParts.length === 1 && userParts[0].type === 'text')
    ? userParts[0].text : userParts;
  msgs.push({ role: 'user', content: userContent });

  const genCfg = rawBody.generationConfig || {};
  const body = { model: input._model, messages: msgs };
  if (genCfg.temperature != null) body.temperature = genCfg.temperature;
  if (genCfg.maxOutputTokens) body.max_tokens = genCfg.maxOutputTokens;
  // Kie currently returns code=500 for generic response_format=json_object; prompts enforce JSON and downstream parser validates it.

  return [{ json: { ...input, _adapted_body: body, _auth_header: input._auth_header || `Bearer ${input._api_key}` } }];
}

// gemini_native: pass through body unchanged
const nativeBody = input.request_body || {
  system_instruction: input.system_instruction,
  contents: input.contents,
  generationConfig: input.generationConfig
};
return [{ json: { ...input, _adapted_body: nativeBody, _auth_header: '' } }];

// 响应适配：将 Kie OpenAI 格式响应规整为 Gemini candidates 格式，供下游节点透明消费
const input = $json;
const adapter = input._adapter || 'gemini_native';

if (adapter === 'kie_openai_chat') {
  // Detect error response before extracting content
  if (input && typeof input === 'object' && !input.choices) {
    const errCode = input.code;
    const errMsg  = input.msg || input.message;
    if (errCode !== undefined && errMsg) {
      const hint =
        String(errCode) === '422' ? '模型不支持或参数错误' :
        String(errCode) === '401' ? 'API Key 无效' :
        String(errCode) === '403' ? '账户权限不足或余额不足' :
        String(errCode) === '429' ? '请求频率超限' : '';
      throw new Error(`Kie API 错误 ${errCode}: ${errMsg}${hint ? '（' + hint + '）' : ''}`);
    }
    if (input.error) {
      const e = input.error;
      throw new Error(`API 错误: ${typeof e === 'string' ? e : (e.message || JSON.stringify(e))}`);
    }
  }
  const content = input?.choices?.[0]?.message?.content ?? '';
  const text = typeof content === 'object' ? JSON.stringify(content) : String(content);
  return [{ json: {
    ...input,
    candidates: [{ content: { parts: [{ text }] } }],
    _raw_kie_response: { choices: input.choices, usage: input.usage, model: input.model }
  }}];
}

// gemini_native: pass through unchanged
return [{ json: input }];
